    assert id_derivation_material(value) == b'april.output-id.v1\x00["task",1,"event",0]'
    assert id_derivation_material(decode_wire(IdDerivationInput, value.model_dump_json().encode())) == id_derivation_material(value)
    variants = [{}, {"segment_no": 2}, {"output_kind": "claim"}, {"local_output_index": 1}, {"task_id": "task/other"}]
    assert len({id_derivation_material(IdDerivationInput(**{**value.model_dump(), **change})) for change in variants}) == len(variants)
    assert id_derivation_material(IdDerivationInput(task_id="é", segment_no=1, output_kind="event", local_output_index=0)) != id_derivation_material(IdDerivationInput(task_id="e\u0301", segment_no=1, output_kind="event", local_output_index=0))
